        "snapshot_ids": [
          "snapshot::dea5130f2fbcac109466b46f"
        ]
      },
      {
        "atom_id": "atom::6f23f085b1ffa8ce1ede256a",
        "source_handle": "P0172",
        "field_path": [
          "study_summary_A",
          "work_summary"
        ],
        "value": "This review article synthesizes current research on how intestinal organoids serve as a bridge for understanding host-microbiota crosstalk within the tumor microenvironment. It details the technical advantages of organoids over traditional 2D cultures and animal models, classifies different types of organoid models, and discusses their applications in deciphering carcinogenic mechanisms driven by microbial dysbiosis, validating tumor-specific microbial features, and exploring bidirectional regulatory mechanisms of microbial metabolites. The paper also addresses the integration of multi-omics technologies and organ-on-a-chip systems to enhance physiological relevance, while critically evaluating limitations such as the lack of complete immune/stromal components and challenges in clinical translation.",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::dea5130f2fbcac109466b46f"
        ]
      },
